import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
import {journalLines} from '../live-paper/journal-lines.mjs';
import {validateTiming,timingDistribution} from '../live-paper/read-timing.mjs';
const args=process.argv.slice(2),arg=(key,otherwise)=>{const i=args.indexOf(key);return i<0?otherwise:args[i+1];},runtime=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime');
const from=arg('--from',null),through=arg('--through',new Date().toISOString());if(!from||!Number.isFinite(Date.parse(from))||!Number.isFinite(Date.parse(through))||Date.parse(through)<=Date.parse(from))throw Error('POSTDEPLOYMENT_WINDOW_REQUIRED');
const sha=b=>createHash('sha256').update(b).digest('hex'),inWindow=at=>Date.parse(at)>=Date.parse(from)&&Date.parse(at)<Date.parse(through);
const seal=file=>{const size=fs.statSync(file).size,fd=fs.openSync(file,'r'),b=Buffer.alloc(Math.min(size,1048576));try{fs.readSync(fd,b,0,b.length,size-b.length);}finally{fs.closeSync(fd);}const last=b.lastIndexOf(10);if(last<0)throw Error('POSTDEPLOYMENT_EMPTY_SOURCE');return size-b.length+last+1;};
const raw=fs.readFileSync(path.join(runtime,'read-timings.jsonl'),'utf8'),complete=raw.slice(0,raw.lastIndexOf('\n')+1),lines=complete.trimEnd().split('\n').map(line=>({line,event:validateTiming(JSON.parse(line))})).filter(({event})=>inWindow(event.queuedAt)&&Date.parse(event.finishedAt)<Date.parse(through)),events=lines.map(x=>x.event),groups={};
for(const e of events){const g=groups[e.kind]??={requests:0,totalClientMs:0,serviceMs:0,admissionMs:0};g.requests++;g.totalClientMs+=e.totalMs||0;g.serviceMs+=e.serviceMs||0;g.admissionMs+=e.admissionWaitMs||0;}
const recurrence={};for(const id of ['195','356','305','306']){const rows=events.filter(e=>e.kind==='book'&&e.marketId===id);recurrence[id]=timingDistribution(rows.slice(1).map((r,i)=>Date.parse(r.finishedAt)-Date.parse(rows[i].finishedAt)));}
const outsideClientGapMs=timingDistribution(events.slice(1).map((e,i)=>Math.max(0,Date.parse(e.queuedAt)-Date.parse(events[i].finishedAt)))),bookServiceMs=timingDistribution(events.filter(e=>e.kind==='book').map(e=>e.serviceMs)),bookAdmissionMs=timingDistribution(events.filter(e=>e.kind==='book').map(e=>e.admissionWaitMs)),eventLoopMaxMs=timingDistribution(events.map(e=>e.eventLoopMaxMs));
