const scopes=[];for(const line of journalLines(accountFile,{endByte:seal(accountFile)})){const r=JSON.parse(line);if(r.event?.type==='market_account_eligibility'&&inWindow(r.at))scopes.push({knownAt:r.at,ordersAt:r.event.snapshot.ordersAt});}
const books=[];for(const line of journalLines(bookFile,{endByte:seal(bookFile)})){const r=JSON.parse(line);if(r.kind==='book'&&inWindow(r.at))books.push({at:r.at,marketId:r.payload.book.marketId,levels:[r.payload.book.bids.length,r.payload.book.asks.length],sequence:r.sequence,hash:r.hash});}
const cycles=scopes.slice(0,-1).map((s,i)=>({accountEligibilityAt:s.knownAt,until:scopes[i+1].knownAt,ordinaryPublishedBooks:books.filter(b=>Date.parse(b.at)>=Date.parse(s.knownAt)&&Date.parse(b.at)<Date.parse(scopes[i+1].knownAt)).map(b=>b.marketId)}));
const runtimeStats=JSON.parse(fs.readFileSync(path.join(runtime,'stats.json'))).runtime,pid=Number(arg('--pid',runtimeStats.pid));if(runtimeStats.pid!==pid||runtimeStats.status!=='running'||runtimeStats.profitSprint?.enabled!==true||Date.now()-fs.statSync(path.join(runtime,'stats.json')).mtimeMs>10000)throw Error('POSTDEPLOYMENT_RUNNING_SPRINT_NOT_VERIFIED');
if(fs.readFileSync(path.join(process.env.LOCALAPPDATA,'SigTradingCup','bot.lock'),'utf8')!==String(pid))throw Error('POSTDEPLOYMENT_COLLECTOR_LOCK_MISMATCH');process.kill(pid,0);
if(runtimeStats.scheduling.reads.length>4||books.some(b=>b.levels.some(n=>n>20))||cycles.some(c=>c.ordinaryPublishedBooks.length>4))throw Error('POSTDEPLOYMENT_ORDINARY_DEPTH_OR_CAP');
const baseline=JSON.parse(fs.readFileSync(new URL('./profit-sprint-read-baseline-20261005.json',import.meta.url))),comparisons=Object.fromEntries(['195','356'].map(id=>[id,{baselineMedianMs:baseline.bookRecurrence[id].median,postMedianMs:recurrence[id].median,postIntervals:recurrence[id].count,medianReductionFraction:recurrence[id].median===null?null:1-recurrence[id].median/baseline.bookRecurrence[id].median}]));
const result={schemaVersion:1,observedFrom:from,observedThrough:through,createdAt:new Date().toISOString(),windowSeconds:(Date.parse(through)-Date.parse(from))/1000,readTimingsWindowSha256:sha(lines.map(x=>x.line+'\n').join('')),requests:events.length,groups,outsideClientGapMs,bookServiceMs,bookAdmissionMs,eventLoopMaxMs,bookRecurrence:recurrence,baselineComparisons:comparisons,collector:{pid:runtimeStats.pid,processAlive:true,collectorLockMatches:true,status:runtimeStats.status,statsFileAgeMs:Date.now()-fs.statSync(path.join(runtime,'stats.json')).mtimeMs,lastCycleAt:runtimeStats.lastCycleAt,profitSprint:runtimeStats.profitSprint,auxiliaryReadAllocation:runtimeStats.auxiliaryReadAllocation,marketSweepRequestedBatches:runtimeStats.marketSweep.requestedBatches,scheduledMarketIds:runtimeStats.scheduling.reads.map(x=>x.marketId),networkBudget:runtimeStats.networkBudget},ordinaryPublication:{source:'public-books.jsonl plus existing causal account-eligibility boundaries',completedCycleWindows:cycles.length,cycles,books:books.length,maximumLevelsObserved:Math.max(0,...books.flatMap(b=>b.levels)),fourBookCapObserved:true,depth20EndpointSourceVerified:fs.readFileSync(new URL('../live-paper/runner.mjs',import.meta.url),'utf8').includes("'&depth=20'"),runnerSourceSha256:sha(fs.readFileSync(new URL('../live-paper/runner.mjs',import.meta.url)))},platformBudgetChanged:false,extraAccountClients:0,contestOrdersSubmittedByProfiler:0,profitabilityEstablished:false,limitations:['A short subsequent window measures current cadence, not long-run tail reliability or profit.','Baseline and subsequent windows have different market/load conditions and are not a controlled causal benchmark.','Timing kind book may include separate realtime recovery reads; ordinary published receipts and cycle cap are checked separately.','Stats health is verified by PID/mtime/status; the parent independently verifies CIM command/lock identity.']};
fs.writeFileSync(new URL('./profit-sprint-read-postdeployment-20261005.json',import.meta.url),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({pid,requests:result.requests,groups,recurrence,comparisons,completedCycles:cycles.length,sprint:runtimeStats.profitSprint.enabled}));
